const localVerifyEmailDomain = `-- name: LocalVerifyEmailDomain :exec
UPDATE organization_metadata
SET verified_domains = array_append(COALESCE(verified_domains, '{}'), $1::text)
WHERE id = $2::text
  AND $1::text <> ''
  AND NOT EXISTS (
      SELECT 1 FROM unnest(COALESCE(verified_domains, '{}')) AS d WHERE lower(d) = lower($1::text)
  )
`

type LocalVerifyEmailDomainParams struct {
	Domain         string
	OrganizationID string
}

// The developer's email domain is verified locally so a dev-idp SSO sign-in
// passes the SSO identity check end to end.
func (q *Queries) LocalVerifyEmailDomain(ctx context.Context, arg LocalVerifyEmailDomainParams) error {
	_, err := q.db.Exec(ctx, localVerifyEmailDomain, arg.Domain, arg.OrganizationID)
	return err
}
